/** 
 * Adds an  {@link OnMediaItemChangedListener} for the given track type.<p>There can't be more than one  {@link OnMediaItemChangedListener} for the same track type.<p>Must be called from the thread used by the current  {@link AssetLoader} to pass data to the{@link SampleConsumer}.
 * @param onMediaItemChangedListener The {@link OnMediaItemChangedListener}.
 * @param trackType The {@link C.TrackType} for which to listen to {@link MediaItem} changeevents. Must be  {@link C#TRACK_TYPE_AUDIO} or {@link C#TRACK_TYPE_VIDEO}.
 */
public void addOnMediaItemChangedListener(OnMediaItemChangedListener onMediaItemChangedListener,@C.TrackType int trackType){
  checkArgument(trackType == C.TRACK_TYPE_AUDIO || trackType == C.TRACK_TYPE_VIDEO);
  checkArgument(mediaItemChangedListenersByTrackType.get(trackType) == null);
  mediaItemChangedListenersByTrackType.put(trackType,onMediaItemChangedListener);
}
